def collapse_whitespace(s):
    result = []
    in_space = False
    for ch in s:
        if ch in ' \t\r\n\x0b\x0c':
            if not in_space:
                result.append(' ')
                in_space = True
        else:
            result.append(ch)
            in_space = False
    while result and result[0] == ' ':
        result.pop(0)
    while result and result[-1] == ' ':
        result.pop()
    return ''.join(result)

